<?php
declare(strict_types=1);use ImAuthenticator\Security;use ImAuthenticator\Web;$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$admin=$auth->requireAdmin();$id=(int)($_GET['id']??0);$target=$db->one('SELECT id,name,email FROM users WHERE id=?',[$id]);if(!$target){http_response_code(404);Web::page('Nie znaleziono','<div class="alert danger">Nie znaleziono użytkownika.</div>',$admin);}$message='';if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);try{$key=trim((string)($_POST['attribute_key']??''));if(!preg_match('/^[A-Za-z0-9][A-Za-z0-9._-]{0,119}$/',$key)||str_starts_with($key,'scim.'))throw new RuntimeException('Nieprawidłowy lub zarezerwowany klucz.');if((string)($_POST['action']??'save')==='delete')$db->execute("DELETE FROM user_attributes WHERE user_id=? AND attribute_key=? AND source='manual'",[$id,$key]);else{$value=trim((string)($_POST['attribute_value']??''));$db->execute("INSERT INTO user_attributes(user_id,attribute_key,attribute_value,source) VALUES(?,?,?,'manual') ON DUPLICATE KEY UPDATE attribute_value=VALUES(attribute_value),source=IF(source='manual','manual',source)",[$id,$key,$value]);}$audit->write('user.attribute.changed','success',(int)$admin['id'],$id,null,null,['attribute'=>$key]);$message='<div class="alert success">Zapisano.</div>';}catch(Throwable$e){$message='<div class="alert danger">'.Web::e($e->getMessage()).'</div>';}}$rows='';foreach($db->all('SELECT * FROM user_attributes WHERE user_id=? ORDER BY attribute_key',[$id])as$a){$manual=$a['source']==='manual';$rows.='<tr><td><code>'.Web::e($a['attribute_key']).'</code></td><td>'.Web::e($a['attribute_value']).'</td><td>'.Web::e($a['source']).'</td><td>'.($manual?'<form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="attribute_key" value="'.Web::e($a['attribute_key']).'"><button class="danger" name="action" value="delete">Usuń</button></form>':'<span class="muted">zarządzane przez sync</span>').'</td></tr>';}$content='<div class="page-head"><div><h1>Custom attributes</h1><p>'.Web::e($target['name'].' — '.$target['email']).'</p></div><a class="button" href="/admin/users/'.$id.'/applications">Aplikacje użytkownika</a></div>'.$message.'<section class="card"><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><label>Klucz<input name="attribute_key" placeholder="department" required></label><label>Wartość<input name="attribute_value"></label><button class="primary" name="action" value="save">Zapisz</button></form></section><div class="table-wrap"><table><thead><tr><th>Klucz</th><th>Wartość</th><th>Źródło</th><th></th></tr></thead><tbody>'.($rows?:'<tr><td colspan="4">Brak atrybutów.</td></tr>').'</tbody></table></div>';Web::page('Custom attributes',$content,$admin);
